    ('tools/clarify_tool.py', '# Applied to the first choice here (not per-surface) so every adapter renders it identically.\nRECOMMENDED_LABEL = "(Recommended)"',
     '# 展示层的"推荐"标记（2026-09-30 改）：原来这里的英文标签会被自动加到第一个选项后面，\n# 经纪人看到的是"某城市 （推荐）"那种英文 + 被替他做主的组合。现在：① 不再自动加标记（见 mark_recommended）；\n# ② 万一手写/历史数据里带中文标记"（推荐）"，剥离时认得出来。\nRECOMMENDED_LABEL = "（推荐）"'),
    ('tools/clarify_tool.py', '    """Suffix the first choice (schema says best-first) with RECOMMENDED_LABEL; idempotent,\n    and a lone choice is left untouched (nothing to prefer it over)."""\n    first = str(choices[0]).strip() if choices else ""\n    if len(choices) < 2 or first != strip_recommended(first):\n        return choices\n    return [f"{first} {RECOMMENDED_LABEL}"] + list(choices[1:])',
     '    """不再给选项加"推荐"标记（2026-09-30 COCO-PATCH，原为给第一个选项补一个英文"推荐"标签）。\n\n    为什么去掉：① 那是英文，经纪人面对的是中文对话；② 它等于**替经纪人做选择**（实测：问"哪个城市的政策"，\n    选项里的外地城市被标成"推荐"，而他做的是另一个城市）。选项顺序仍可"最合适的在前"，但界面不再替他表态。\n    保留函数名与 strip_recommended，是为了兼容历史/手写标记仍能被剥离。\n    """\n    return list(choices)'),
    ('tools/clarify_tool.py', '    # The bare list goes back to the agent; the "(Recommended)" label is presentation only.',
     '    # The bare list goes back to the agent; the presentation layer no longer tags a "推荐"选项。'),
    ('tools/clarify_tool.py', '        f"single-select (up to {MAX_CHOICES} choices — put your recommended "\n        "option FIRST, the UI marks it \'(Recommended)\' and auto-appends an "\n        "\'Other\' free-text row), multi-select (multi_select=true), or "',
     '        f"single-select (up to {MAX_CHOICES} choices — put the most suitable "\n        "option FIRST and let the user pick; the UI does not mark any option "\n        "as recommended. Some surfaces append an \'Other\' free-text row and "\n        "some do not — when in doubt add your own \'其他（我来补充）\' as the last "\n        "choice), multi-select (multi_select=true), or "'),
    ('hermes_cli/doctor_platform.py', 'def _check_command_installation(should_fix: bool, f: Finding) -> None:\n    """Venv entry point and the ~/.local/bin (or $PREFIX/bin) symlink; skipped on Windows."""\n    from hermes_cli.doctor import PROJECT_ROOT\n    if sys.platform == "win32":\n        return\n    _section("Command Installation")\n    venv_bin = next((c for c in (PROJECT_ROOT / n / "bin" / "hermes" for n in ("venv", ".venv")) if c.exists()), None)\n    if venv_bin is None:\n        check_warn("Venv entry point not found", "(hermes not in venv/bin/ or .venv/bin/ — reinstall with pip install -e \'.[all]\')")\n        return f.manual_issues.append(f"Reinstall entry point: cd {PROJECT_ROOT} && source venv/bin/activate && pip install -e \'.[all]\'")\n    check_ok(f"Venv entry point exists ({venv_bin.relative_to(PROJECT_ROOT)})")\n    # Expected command link directory (mirrors install.sh logic).\n    prefix = os.environ.get("PREFIX", "")\n    termux = prefix and (os.environ.get("TERMUX_VERSION") or "com.termux/files/usr" in prefix)\n    link_dir, display = (Path(prefix) / "bin", "$PREFIX/bin") if termux else (Path.home() / ".local" / "bin", "~/.local/bin")\n    link = link_dir / "hermes"\n    if link.is_symlink():\n        target, expected = link.resolve(), venv_bin.resolve()\n        if target == expected:\n            return check_ok(f"{display}/hermes → correct target")\n        check_warn(f"{display}/hermes points to wrong target", f"(→ {target}, expected → {expected})")\n        if not should_fix:\n            return f.issues.append(f"Broken symlink at {display}/hermes — run \'hermes doctor --fix\'")\n        link.unlink()\n        verb = "Fixed"\n    elif link.exists():  # regular file (wrapper script), not a symlink\n        return check_ok(f"{display}/hermes exists (non-symlink)")\n    else:\n        check_fail(f"{display}/hermes not found", "(hermes command may not work outside the venv)")\n        if not should_fix:\n            return f.issues.append(f"Missing {display}/hermes symlink — run \'hermes doctor --fix\'")\n        link_dir.mkdir(parents=True, exist_ok=True)\n        verb = "Created"\n    link.symlink_to(venv_bin)\n    check_ok(f"{verb} symlink: {display}/hermes → {venv_bin}")\n    f.fixed += 1\n    if verb == "Created" and str(link_dir) not in os.environ.get("PATH", "").split(os.pathsep):\n        check_warn(f"{display} is not on your PATH", "(add it to your shell config: export PATH=\\"$HOME/.local/bin:$PATH\\")")\n        f.manual_issues.append(f"Add {display} to your PATH")',
     'def _check_command_installation(should_fix: bool, f: Finding) -> None:\n    """Venv entry point and the ~/.local/bin (or $PREFIX/bin) symlink; skipped on Windows."""\n    from hermes_cli.doctor import PROJECT_ROOT\n    if sys.platform == "win32":\n        return\n    _section("命令入口")\n    venv_bin = next((c for c in (PROJECT_ROOT / n / "bin" / "hermes" for n in ("venv", ".venv")) if c.exists()), None)\n    if venv_bin is None:\n        check_warn("虚拟环境入口缺失", "（venv/bin/ 或 .venv/bin/ 里没有 hermes —— 用 pip install -e \'.[all]\' 重装）")\n        return f.manual_issues.append(f"重装入口：cd {PROJECT_ROOT} && source venv/bin/activate && pip install -e \'.[all]\'")\n    check_ok(f"虚拟环境入口在位（{venv_bin.relative_to(PROJECT_ROOT)}）")\n    # 命令链接目录：与 install.sh 的 get_command_link_dir 同一套规则 ——\n    # Termux 用 $PREFIX/bin；root/FHS 装法用 /usr/local/bin；其余用 ~/.local/bin。\n    # 只看一个目录会误报：root 装法的链接在 /usr/local/bin，体检却只查 ~/.local/bin。\n    # Coco 只对外暴露 coco 命令（安装与更新会移除 hermes 软链），所以这里查的是 coco 链接。\n    _coco_only = (PROJECT_ROOT / "scripts" / "coco.sh").exists()\n    link_name = "coco" if _coco_only else "hermes"\n    prefix = os.environ.get("PREFIX", "")\n    termux = prefix and (os.environ.get("TERMUX_VERSION") or "com.termux/files/usr" in prefix)\n    if termux:\n        candidates = [(Path(prefix) / "bin", "$PREFIX/bin")]\n    elif os.geteuid() == 0:\n        candidates = [(Path("/usr/local/bin"), "/usr/local/bin"), (Path.home() / ".local" / "bin", "~/.local/bin")]\n    else:\n        candidates = [(Path.home() / ".local" / "bin", "~/.local/bin"), (Path("/usr/local/bin"), "/usr/local/bin")]\n    dirty_link = None\n    for link_dir, display in candidates:\n        link = link_dir / link_name\n        if link.is_symlink():\n            target, expected = link.resolve(), venv_bin.resolve()\n            if target == expected:\n                return check_ok(f"{display}/{link_name} → 指向正确")\n            check_warn(f"{display}/{link_name} 指向的目标不对", f"（→ {target}，应该是 → {expected}）")\n            if not should_fix:\n                return f.issues.append(f"{display}/{link_name} 是坏链接 —— 跑「coco doctor --fix」")\n            link.unlink()\n            link.symlink_to(venv_bin)\n            check_ok(f"已修复链接：{display}/{link_name} → {venv_bin}")\n            f.fixed += 1\n            return\n        if link.exists():  # regular file (wrapper script), not a symlink\n            return check_ok(f"{display}/{link_name} 存在（是普通文件）")\n        if dirty_link is None:\n            dirty_link = (link_dir, display)\n    link_dir, display = dirty_link\n    looked = "、".join(d for _, d in candidates)\n    check_fail(f"找不到 {link_name} 命令链接", f"（{looked} 都查过）")\n    if not should_fix:\n        return f.issues.append(f"缺 {link_name} 命令链接 —— 跑「coco doctor --fix」")\n    link_dir.mkdir(parents=True, exist_ok=True)\n    link = link_dir / link_name\n    link.symlink_to(venv_bin)\n    check_ok(f"已创建链接：{display}/{link_name} → {venv_bin}")\n    f.fixed += 1\n    if str(link_dir) not in os.environ.get("PATH", "").split(os.pathsep):\n        check_warn(f"{display} 不在你的 PATH 里", f"（加到你的 shell 配置里：export PATH=\\"{display}:$PATH\\"）")\n        f.manual_issues.append(f"把 {display} 加到 PATH 里")'),
